INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(24801, 'Luke 22:64', 'Luke', 22, 64, '&nbsp;سترګې يې ورله وتړلې او د هغۀ نه يې بار بار دا تپوسونه کول، ”کۀ تۀ نبى يې نو مونږ ته دا ووايه چې تۀ چا ووهلې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24802, 'Luke 22:65', 'Luke', 22, 65, '&nbsp;او دغه شان هغوئ د هغۀ نور ډېر سپکاوے هم کولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24803, 'Luke 22:66', 'Luke', 22, 66, '&nbsp;چې ورځ شوه نو اولسى مشران، مشران اِمامان او د شرعې عالمان راټول شول او عيسىٰ يې د خپلې جرګې وړاندې پېش کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24804, 'Luke 22:67', 'Luke', 22, 67, '&nbsp;هغوئ ووئيل، ”مونږ ته ووايه چې تۀ په رښتيا مسيح يې؟“ هغۀ جواب ورکړو، ”کۀ زۀ درته وايم نو تاسو به په ما يقين ونۀ کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24805, 'Luke 22:68', 'Luke', 22, 68, '&nbsp;او کۀ زۀ درنه تپوس وکړم نو تاسو به جواب رانۀ کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24806, 'Luke 22:69', 'Luke', 22, 69, '&nbsp;خو د دې نه پس به اِبن آدم د خُدائ پاک ښى لاس ته ناست وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24807, 'Luke 22:70', 'Luke', 22, 70, '&nbsp;هغوئ ټولو ووئيل، ”نو بيا تۀ د خُدائ پاک زوئ يې څۀ؟“ هغۀ جواب ورکړو، ”دا تاسو وايئ چې زۀ يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24808, 'Luke 22:71', 'Luke', 22, 71, '&nbsp;بيا هغوئ ووئيل، ”ولې د دې نه پس مونږ ته د نورې ګواهۍ حاجت شته څۀ؟ مونږ د دۀ د خپلې خولې نه په خپله دا خبره واورېده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24809, 'Luke 23:1', 'Luke', 23, 1, '&nbsp;د دې سره ټوله غونډه پاڅېدله او عيسىٰ يې پيلاطوس له بوتلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24810, 'Luke 23:2', 'Luke', 23, 2, '&nbsp;او په دې وينا يې د هغۀ خلاف دعوىٰ شروع کړه، ”مونږ دا سړے وليدلو چې زمونږ د قوم خلق بې‌لارې کوى او قيصر ته د محصُول ورکولو نه خلق منع کوى او وائى چې زۀ مسيح بادشاه يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24811, 'Luke 23:3', 'Luke', 23, 3, '&nbsp;بيا پيلاطوس د هغۀ نه تپوس وکړو، ”ولې تۀ د يهوديانو بادشاه يې څۀ؟“ هغۀ وفرمائيل چې، ”دا ستا وينا ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24812, 'Luke 23:4', 'Luke', 23, 4, '&nbsp;نو بيا پيلاطوس مشرانو اِمامانو او حاضرو خلقو ته ووئيل چې، ”زۀ په دې سړى کښې هيڅ جرم نۀ وينم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24813, 'Luke 23:5', 'Luke', 23, 5, '&nbsp;خو هغوئ اِصرار وکړو چې، ”د هغۀ تعليمات په ټوله يهوديه کښې خلق بلوه کوى. چې د ګليل نه راشروع شو او تر دې ښاره راورسېدو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24814, 'Luke 23:6', 'Luke', 23, 6, '&nbsp;کله چې پيلاطوس دا واورېدل نو تپوس يې وکړو چې، ”ولې دا سړے ګليلى دے څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24815, 'Luke 23:7', 'Luke', 23, 7, '&nbsp;او چې د دې نه خبر شو چې عيسىٰ د هيروديس د حکومت اختيار لاندې دے نو هغۀ دا مقدمه هيروديس له ولېږله څوک چې په خپله په هغه ورځو کښې د يروشلم په دوره وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24816, 'Luke 23:8', 'Luke', 23, 8, '&nbsp;کله چې هيروديس عيسىٰ وليدو نو ډېر خوشحاله شو ځکه چې د هغۀ په حقله يې اورېدلى وُو او د ډېر وخت نه يې دا خواهش وو چې هغه ووينى او په دې طمع وو چې د هغۀ د لاس نه څۀ معجزه ووينى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24817, 'Luke 23:9', 'Luke', 23, 9, '&nbsp;هيروديس د عيسىٰ نه ډېر تپوسونه وکړل خو هغۀ هيڅ جواب ورنۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24818, 'Luke 23:10', 'Luke', 23, 10, '&nbsp;خو مشران اِمامان او د شرعې عالمان راوړاندې شول او د عيسىٰ خلاف يې سخت اِلزامونه شروع کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24819, 'Luke 23:11', 'Luke', 23, 11, '&nbsp;بيا هيروديس او د هغۀ سپاهيانو د هغۀ سپکاوے وکړو او بې‌عزته يې کړو او په ځلېدونکو جامو کښې يې پيلاطوس له واپس ولېږلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24820, 'Luke 23:12', 'Luke', 23, 12, '&nbsp;هم په هغه ورځ هيروديس او پيلاطوس دوستان شول، د دې نه وړاندې دوئ په خپلو کښې دشمنان وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24821, 'Luke 23:13', 'Luke', 23, 13, '&nbsp;پيلاطوس بيا مشران اِمامان، مشران او څۀ نور خلق راوبلل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24822, 'Luke 23:14', 'Luke', 23, 14, '&nbsp;او ورته يې ووئيل، ”تاسو دا سړے ما ته د خلقو د بې‌لارې کولو په اِلزام کښې راوستے دے خو لکه چې تاسو ګورئ ما په خپله ستاسو په وړاندې د هغۀ نه معلومات وکړو او په هغۀ کښې مې هغه جرم ونۀ موندلو چې تاسو پرې د کوم دعوىٰ کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24823, 'Luke 23:15', 'Luke', 23, 15, '&nbsp;او نۀ هيروديس په کښې څۀ وموندل ځکه چې هغۀ هغه واپس ما له راولېږلو. دې نه دا پته لګى چې دۀ داسې څۀ جرم نۀ دے کړے چې د مرګ لائق وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24824, 'Luke 23:16', 'Luke', 23, 16, '&nbsp;نو زما په خيال د يو څو کوړو سزا تېرولو نه وروستو به يې پرېږدم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24825, 'Luke 23:17', 'Luke', 23, 17, '&nbsp;د اختر په موقع به هغۀ ته دا اجازت وو چې د هغوئ په وينا يو قېدى آزاد کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24826, 'Luke 23:18', 'Luke', 23, 18, '&nbsp;خو هغوئ ټولو په جمع شور جوړ کړو، ”دا سړے ختم کړه. مونږ ته برابا آزاد کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24827, 'Luke 23:19', 'Luke', 23, 19, '&nbsp;برابا هغه څوک وو چې په ښار کښې د بغاوت او قتل په اِلزام کښې قېد کړے شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24828, 'Luke 23:20', 'Luke', 23, 20, '&nbsp;پيلاطوس هغوئ ته بيا مخاطب شو او دا يې غوښتل چې عيسىٰ آزاد کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24829, 'Luke 23:21', 'Luke', 23, 21, '&nbsp;خو هغوئ چغې وهلې، ”دے په سولۍ راځوړند کړئ. دے په سولۍ راځوړند کړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24830, 'Luke 23:22', 'Luke', 23, 22, '&nbsp;پيلاطوس په درېم ځل بيا هغوئ ته ووئيل، ”ولې؟ دۀ څۀ ګناه کړې ده؟ ما هغۀ کښې داسې څۀ جرم ونۀ ليدو چې د مرګ سزا ورکړم، ځکه زۀ به د کوړو سزا ورکړم او بيا به يې آزاد کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24831, 'Luke 23:23', 'Luke', 23, 23, '&nbsp;خو هغوئ په ټينګه او په چغو ووئيل چې، ”دے دې په سولۍ کړے شى.“ او د هغوئ چغې ومنلے شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24832, 'Luke 23:24', 'Luke', 23, 24, '&nbsp;نو پيلاطوس دا فېصله وکړه چې د هغوئ د خوښې کار دې وشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24833, 'Luke 23:25', 'Luke', 23, 25, '&nbsp;هغۀ هغه سړے آزاد کړو چې هغوئ غوښتو څوک چې د بغاوت او قتل په جرم کښې قېد شوے وو، او عيسىٰ يې د هغوئ مرضۍ ته وسپارلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24834, 'Luke 23:26', 'Luke', 23, 26, '&nbsp;چې هغوئ عيسىٰ په سولۍ کولو له بوتلو نو شمعون کرينى نومې سړے يې راونيولو چې د کلى نه راتلو، سولۍ يې هغۀ ته په اوږه کړه او هغه يې عيسىٰ پسې روان کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24835, 'Luke 23:27', 'Luke', 23, 27, '&nbsp;ډېر خلق ورپسې وُو چې په کښې ګڼې ښځې هم وې، چې ځانونه يې وهل او په هغۀ يې وير کولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24836, 'Luke 23:28', 'Luke', 23, 28, '&nbsp;عيسىٰ هغوئ ته مخ راواړولو او ورته يې وفرمائيل، ”اے د يروشلم لوڼو. ما پسې ژړا مۀ کوئ خو په خپل ځان او د خپل اولاد دپاره وير وکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24837, 'Luke 23:29', 'Luke', 23, 29, '&nbsp;ځکه چې هغه ورځې راتلونکې دى چې هغوئ به وائى چې شنډې بختورې دى، چې کله يې هم بچى نۀ دى راوړى او کله يې هم سينه نۀ ده ورکړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24838, 'Luke 23:30', 'Luke', 23, 30, '&nbsp;بيا به هغوئ غرونو ته وائى چې په مونږ راورغړئ. او غونډو ته به وائى چې مونږ پټ کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24839, 'Luke 23:31', 'Luke', 23, 31, '&nbsp;ځکه چې د شنې ونې دا حال وى نو د وچې به څۀ حال وى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24840, 'Luke 23:32', 'Luke', 23, 32, '&nbsp;د عيسىٰ نه بغېر دوه نور مجرمان هم وُو چې هغۀ سره په سولۍ کولو له بوتلے شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24841, 'Luke 23:33', 'Luke', 23, 33, '&nbsp;کله چې هغوئ کوپړۍ نومې ځائ ته ورسېدل نو هلته يې هغه د دوو مجرمانو سره په سولۍ کړو. يو يې د هغۀ ښى او بل يې ورسره ګس لاس ته راځوړند کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24842, 'Luke 23:34', 'Luke', 23, 34, '&nbsp;عيسىٰ وفرمائيل، ”پلاره، دوئ معاف کړه. ځکه چې هغوئ نۀ پوهيږى چې څۀ کوى.“ سپاهيانو د هغۀ په جامو خسڼے واچولو او په خپلو کښې يې وويشلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24843, 'Luke 23:35', 'Luke', 23, 35, '&nbsp;او خلق يې تماشې ته ولاړ وُو او د هغوئ حاکمانو په هغۀ پورې ټوقې کولې، ”هغۀ خو نور خلق بچ کول، اوس دې خپل ځان بچ کړى کۀ چرې دے په رښتيا د خُدائ پاک غوره شوے مسيح وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24844, 'Luke 23:36', 'Luke', 23, 36, '&nbsp;سپاهيانو هم په هغۀ پورې ټوقې وکړې او هغۀ له يې سرکه ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24845, 'Luke 23:37', 'Luke', 23, 37, '&nbsp;او ورته يې وئيل چې، ”کۀ چرې تۀ د يهوديانو بادشاه يې نو خپل ځان بچ کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24846, 'Luke 23:38', 'Luke', 23, 38, '&nbsp;د هغۀ د سر دپاسه يې يوه تختۍ لګولې وه چې پرې داسې ليکل وُو چې، ”دا د يهوديانو بادشاه دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24847, 'Luke 23:39', 'Luke', 23, 39, '&nbsp;په هغه مجرمانو کښې يو چې ورسره په څنګ کښې راځوړند وو عيسىٰ ته پېغور ورکړو، ”ولې تۀ مسيح نۀ يې څۀ؟ نو بيا خپل ځان او مونږ هم بچ کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24848, 'Luke 23:40', 'Luke', 23, 40, '&nbsp;خو دوېم مجرم په دې هغه ورټلو او ورته يې ووئيل چې، ”تۀ د خُدائ پاک نه نۀ يرېږې څۀ؟ تا ته هم د دۀ په شان سزا درکولے کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24849, 'Luke 23:41', 'Luke', 23, 41, '&nbsp;مونږ سره خو اِنصاف شوے دے. مونږ ته خو د خپل عمل سزا مِلاو شوه، ولې دۀ خو هيڅ بد کار نۀ دے کړے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24850, 'Luke 23:42', 'Luke', 23, 42, '&nbsp;او هغۀ ورته ووئيل، ”اے عيسىٰ، کله چې تۀ خپلې بادشاهۍ ته ورسيږى نو ما هم ياد ساته.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24851, 'Luke 23:43', 'Luke', 23, 43, '&nbsp;عيسىٰ جواب ورکړو، ”زۀ تا ته دا وايم چې تۀ به نن ما سره په جنت فردوس کښې يو ځائ يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24852, 'Luke 23:44', 'Luke', 23, 44, '&nbsp;د غرمې وخت وو او په ټوله زمکه تيارۀ راخوره شوه او د ماسپښين تر درېو بجو پورې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24853, 'Luke 23:45', 'Luke', 23, 45, '&nbsp;نمر پټ شو او د خُدائ د کور پړده په مينځ دوه شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24854, 'Luke 23:46', 'Luke', 23, 46, '&nbsp;نو بيا عيسىٰ يوه تېزه کريکه وويسته او وې فرمائيل، ”اے پلاره، زۀ خپل روح ستا لاسونو ته سپارم.“ او دې وئيلو سره يې ساه ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24855, 'Luke 23:47', 'Luke', 23, 47, '&nbsp;نو د دې هر څۀ په ليدلو صوبه دار د خُدائ پاک ثنا ووئيله او وې وئيل چې، ”بې‌شکه چې دا سړے بې‌ګناه وو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24856, 'Luke 23:48', 'Luke', 23, 48, '&nbsp;خو هغه ټول خلق چې دې تماشې ته راجمع شوى وُو کله چې هغوئ دا واقعه وليدله نو ماتم يې وکړو او کورونو ته واپس لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24857, 'Luke 23:49', 'Luke', 23, 49, '&nbsp;د عيسىٰ ټول دوستان هلته لرې ولاړ وُو او کومې ښځې چې د ګليل نه ورپسې راغلې وې، هغوئ هم ورسره ولاړې وې او دا هر څۀ هغوئ په خپله وليدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24858, 'Luke 23:50', 'Luke', 23, 50, '&nbsp;نو بيا هلته يوسف نومې يو سړے وو چې د جرګې ممبر او نېک او صادق سړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24859, 'Luke 23:51', 'Luke', 23, 51, '&nbsp;د هغۀ د هغوئ په دې فېصلې او صلاح کښې ورسره راضى نۀ وو. چې د يهوديانو د ارمتيه ښاريې سره يې تعلق وو او د خُدائ پاک د بادشاهۍ په انتظار وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24860, 'Luke 23:52', 'Luke', 23, 52, '&nbsp;نو هغه بيا پيلاطوس له لاړو او د عيسىٰ لاش يې ترې وغوښتو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24861, 'Luke 23:53', 'Luke', 23, 53, '&nbsp;بيا هغۀ لاش د سولۍ نه راکوز کړو او د کتان کفن يې ورکړو او په غار کښې يې په کنستلے شوى قبر کښې کېښودو چې د دې نه وړاندې په کښې څوک اېښودے شوے نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24862, 'Luke 23:54', 'Luke', 23, 54, '&nbsp;دا د تيارۍ کولو ورځ وه او د سبت ورځ شروع کېدونکې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24863, 'Luke 23:55', 'Luke', 23, 55, '&nbsp;کومې ښځې چې ورسره د ګليل نه راغلې وې هغوئ يوسف پسې وې او هغوئ قبر په نښه کړو او دا يې کتل چې د عيسىٰ لاش يې چرته ښخ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24864, 'Luke 23:56', 'Luke', 23, 56, '&nbsp;بيا هغوئ کور ته لاړې او عُود او لوبان يې تيار کړل خو د شريعت په مطابق يې د سبت په ورځ آرام وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24865, 'Luke 24:1', 'Luke', 24, 1, '&nbsp;خو د اِتوار په ورځ سحر وختى هم هغه ښځې قبر له راغلې او هغه تيارې کړې خوشبويۍ يې د ځان سره راوړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24866, 'Luke 24:2', 'Luke', 24, 2, '&nbsp;خو هغوئ د غار نه کاڼے رغړېدلے وليدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24867, 'Luke 24:3', 'Luke', 24, 3, '&nbsp;خو کله چې هغوئ دننه ورغلې هغوئ د مالِک عيسىٰ لاش هلته ونۀ موندلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24868, 'Luke 24:4', 'Luke', 24, 4, '&nbsp;دوئ لا په دې واقعه حېرانې ولاړې وې چې ناګهانه دوه سړى په برېښناکو جامو کښې هغوئ سره ودرېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24869, 'Luke 24:5', 'Luke', 24, 5, '&nbsp;هغوئ يرېدلې او خپل سرونه يې زمکې ته ټيټ کړل خو سړو ورته وفرمائيل چې، ”تاسو ژوندى په مړو کښې ولې لټوئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24870, 'Luke 24:6', 'Luke', 24, 6, '&nbsp;هغه دلته نشته، هغه بيا ژوندے شوے دے. تاسو هغه خبرې رايادې کړئ څۀ وخت چې هغه لا په ګليل کښې وو او درته يې کړې وې', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24871, 'Luke 24:7', 'Luke', 24, 7, '&nbsp;چې، اِبن آدم به ضرور د ګناهګارو سړو لاسونو ته حواله شى او په سولۍ به کړے شى او په درېمه ورځ به بيا ژوندے پاڅى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24872, 'Luke 24:8', 'Luke', 24, 8, '&nbsp;بيا هغوئ ته د عيسىٰ خبرې وريادې شوې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24873, 'Luke 24:9', 'Luke', 24, 9, '&nbsp;او د قبر نه په واپسۍ هغوئ دا ټولې خبرې هغه يوولسو مريدانو او نورو ټولو خلقو ته واورولې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24874, 'Luke 24:10', 'Luke', 24, 10, '&nbsp;دا مريم مګدلينى، يوانه او د يعقوب مور مريم وه او دوئ سره نورې ښځې وې چا چې رسولانو ته دا خبرې وکړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24875, 'Luke 24:11', 'Luke', 24, 11, '&nbsp;خو دا خبرې هغوئ ته بې‌کاره ښکاره شوې او په هغوئ يې باور ونۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24876, 'Luke 24:12', 'Luke', 24, 12, '&nbsp;خو پطروس پاڅېدلو او قبر له په منډه لاړو او چې غار ته ورټيټ شو او دننه يې وکتل نو هغۀ صرف د کتان کفن وليدو، بيا هغه په دې شوې واقعه کور ته په سوچونو کښې ډوب لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24877, 'Luke 24:13', 'Luke', 24, 13, '&nbsp;هم په هغه ورځ اِماوس نومې کلى ته د دوئ نه دوه کسان روان وُو چې د يروشلم نه تقريباً اووۀ ميله لرې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24878, 'Luke 24:14', 'Luke', 24, 14, '&nbsp;هغوئ په خپلو کښې يو بل سره په دې واقعاتو خبرې کولې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24879, 'Luke 24:15', 'Luke', 24, 15, '&nbsp;کله چې هغوئ يو بل سره په دې بحث کښې لګيا وُو نو عيسىٰ په خپله راغلو او د هغوئ سره يو ځائ روان شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24880, 'Luke 24:16', 'Luke', 24, 16, '&nbsp;خو د هغوئ په سترګو پرده اچولے شوې وه د دې دپاره چې هغه ونۀ پېژنى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24881, 'Luke 24:17', 'Luke', 24, 17, '&nbsp;هغۀ د هغوئ نه تپوس وکړو چې، ”دا تاسو په تلو تلو کښې د يو بل سره په څۀ خبره بحث کولو؟“ هغوئ غم زپلى ودرېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24882, 'Luke 24:18', 'Luke', 24, 18, '&nbsp;نو په هغوئ کښې يو کس چې نوم يې کليوپاس وو ورته جواب ورکړو، ”ولې تۀ په يروشلم کښې واحد مسافر يې چې د دې واقعې نه ناخبره يې چې په تېرو څو ورځو کښې هلته څۀ شوى دى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24883, 'Luke 24:19', 'Luke', 24, 19, '&nbsp;هغۀ ورته وفرمائيل چې، ”څۀ شوى دى؟“ هغوئ جواب ورکړو چې، ”د عيسىٰ ناصرى په حقله چې د خُدائ پاک او ټولو خلقو په نظر کښې په کلام او عمل دواړو کښې يو زورَور نبى وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24884, 'Luke 24:20', 'Luke', 24, 20, '&nbsp;او زمونږ مشرانو اِمامانو او حاکمانو هغه حواله کړو چې د مرګ حُکم پرې وشى او په سولۍ يې کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24885, 'Luke 24:21', 'Luke', 24, 21, '&nbsp;خو زمونږ دا طمع وه چې هم دے به بنى اِسرائيلو له خلاصون ورکوى. خو نن درېمه ورځ ده چې دا واقعه شوې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24886, 'Luke 24:22', 'Luke', 24, 22, '&nbsp;خو د دې هر څۀ نه علاوه زمونږ د قبيلې يو څو ښځو مونږ په دې خبره حق حېران کړُو. هغوئ سحر وختى د هغۀ قبر له تلې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24887, 'Luke 24:23', 'Luke', 24, 23, '&nbsp;خو چې هغوئ د هغۀ لاش ونۀ موندو او د دې خبر سره واپس راغلې چې هغوئ ته فرښتې ښکاره شوې او ورته يې وفرمائيل چې عيسىٰ ژوندے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24888, 'Luke 24:24', 'Luke', 24, 24, '&nbsp;نو زمونږ يو څو ملګرى قبر له لاړل او څۀ چې هغه ښځو وئيلى وُو رښتيا هم هغه شان وُو خو هغوئ هغه هلته ونۀ ليدو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24889, 'Luke 24:25', 'Luke', 24, 25, '&nbsp;عيسىٰ جواب ورکړو چې، ”اے نادانو خلقو تاسو څومره ساده ګان يئ چې د نبيانو په کلام مو باور نۀ دے کړے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24890, 'Luke 24:26', 'Luke', 24, 26, '&nbsp;ولې د مسيح دپاره دا مقرر نۀ وُو چې هغه به دا زحمتونه وزغمى او په خپل جلال کښې به داخل شى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24891, 'Luke 24:27', 'Luke', 24, 27, '&nbsp;بيا عيسىٰ د خپل ځان په حقله هغوئ ته د موسىٰ نه راواخله تر ټولو نبيانو پورې هغه خبرې تشريح کړې کومې چې په صحيفو کښې راغلې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24892, 'Luke 24:28', 'Luke', 24, 28, '&nbsp;کله چې هغوئ اِماوس کلى ته نزدې شُو نو عيسىٰ خپل ځان داسې ظاهر کړو چې ګنې لا نور هم مخکښې روان دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24893, 'Luke 24:29', 'Luke', 24, 29, '&nbsp;خو هغوئ هغۀ ته په کلکه ووئيل چې، ”مونږ سره پاتې شه اوس ناوخته دے توره شپه راروانه ده.“ نو هغه ورسره لاړو او د هغوئ سره پاتې شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24894, 'Luke 24:30', 'Luke', 24, 30, '&nbsp;کله چې هغه د هغوئ سره خوراک ته کښېناستو نو روټۍ يې راواخسته، شُکر يې پرې وويستو، ټُکړې يې کړه او هغوئ له يې ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24895, 'Luke 24:31', 'Luke', 24, 31, '&nbsp;بيا د هغوئ سترګې وغړېدلې او هغه يې وپېژندلو خو هغه د هغوئ د نظر نه غېب شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24896, 'Luke 24:32', 'Luke', 24, 32, '&nbsp;هغوئ يو بل ته ووئيل، ”زمونږ په زړونو کښې څومره جذبه راغلې وه. کله چې په لاره هغۀ مونږ سره خبرې کولې او د صحيفو تشريح يې کوله.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24897, 'Luke 24:33', 'Luke', 24, 33, '&nbsp;بيا هغوئ هم په هغه وخت يروشلم ته واپس روان شول. هلته هغوئ د هغه يوولسو مريدانو او نور ملګرو سره ملاقات وکړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24898, 'Luke 24:34', 'Luke', 24, 34, '&nbsp;او وئيل يې، ”دا رښتيا دى چې مالِک راژوندے شوے دے او شمعون ته ښکاره شوے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24899, 'Luke 24:35', 'Luke', 24, 35, '&nbsp;نو بيا هغوئ دواړو ورته د خپلې لارې واقعه بيان کړه چې هغوئ مالِک د روټۍ ماتولو په وخت کښې څنګه وپېژندلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24900, 'Luke 24:36', 'Luke', 24, 36, '&nbsp;مريدانو لا دا خبرې کولې چې ناڅاپه عيسىٰ په خپله د هغوئ په مينځ کښې ودرېدو او ورته يې وفرمائيل، ”السلام عليکم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');